// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.NETM();

        address recipient = address(0x1234);
        uint256 amount = 1000e18;

        bool transferSuccess;
        vm.prank(address(this));
        try c.transfer(recipient, amount) {
            transferSuccess = true;
        } catch {
            transferSuccess = false;
        }

        uint256 recipientBal = c.balanceOf(recipient);

        assertTrue(transferSuccess && recipientBal > 0);
    }
}
